document.addEventListener('DOMContentLoaded',function(){const header = document.querySelector('header');if(header){let lastScrollTop = 0;window.addEventListener('scroll',function(){const scrollTop = window.pageYOffset || document.documentElement.scrollTop;if(scrollTop > 100){header.classList.add('scrolled');}else{header.classList.remove('scrolled');}lastScrollTop = scrollTop;});}const navbarToggler = document.querySelector('.navbar-toggler');const navbarCollapse = document.querySelector('.navbar-collapse');if(navbarToggler && navbarCollapse){navbarToggler.addEventListener('click',function(){navbarCollapse.classList.toggle('show');});}document.querySelectorAll('a[href^="#"]').forEach(anchor =>{anchor.addEventListener('click',function(e){e.preventDefault();const target = document.querySelector(this.getAttribute('href'));if(target){target.scrollIntoView({behavior:'smooth',block:'start',});}});});});